@@ -0,0 +1,22 @@
+export interface HealthCheckStrategy {
+  name: string;
+  interval: number;
+  check(): Promise<{ status: string; detail?: string }>;
+}
+
+export class HealthCheckRegistry {
+  private checks = new Map<string, HealthCheckStrategy>();
+
+  register(check: HealthCheckStrategy): void {
+    this.checks.set(check.name, check);
+  }
+
+  async runAll(): Promise<Record<string, string>> {
+    const results: Record<string, string> = {};
+    for (const [name, strategy] of this.checks) {
+      const r = await strategy.check();
+      results[name] = r.status;
+    }
+    return results;
+  }
+}

